CREATE OR REPLACE FUNCTION public.pos_shipments_page(p_store_id uuid,p_filter text DEFAULT 'pending',p_search text DEFAULT '',p_limit integer DEFAULT 50,p_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
-- NÃO REMOVER: latest 200 is the legacy counter scope, not the downloaded page size.
WITH scope AS MATERIALIZED (SELECT s.id,s.store_id,s.seller_id,s.customer_id,s.subtotal,s.discount,s.total,s.status,s.sale_type,s.payment_gateway,s.expedition_status,s.tracking_code,s.shipped_at,s.shipping_address,s.shipping_notes,s.notes,s.tiny_order_id,s.tiny_order_number,s.created_at,s.payment_details FROM public.pos_sales s WHERE s.store_id=p_store_id AND s.sale_type IN ('online','pickup') AND s.status IN ('completed','paid') ORDER BY s.created_at DESC LIMIT 200), enriched AS MATERIALIZED (
SELECT s.*,c.cep AS customer_cep,c.city AS customer_city,c.state AS customer_state,c.address AS customer_address,COALESCE(seller.name,s.payment_details->>'seller_name') AS seller_name,COALESCE(c.name,fallback.customer_name) AS customer_name,COALESCE(c.whatsapp,fallback.customer_phone) AS customer_phone,COALESCE(items.rows,'[]'::jsonb) AS items FROM scope s LEFT JOIN public.pos_customers c ON c.id=s.customer_id LEFT JOIN public.pos_sellers seller ON seller.id=s.seller_id LEFT JOIN LATERAL (SELECT a.customer_name,a.customer_phone FROM public.pos_checkout_attempts a WHERE a.sale_id=s.id::text AND s.customer_id IS NULL AND a.customer_name IS NOT NULL ORDER BY a.created_at ASC LIMIT 1) fallback ON true LEFT JOIN LATERAL (SELECT jsonb_agg(jsonb_build_object('id',i.id,'sku',i.sku,'product_name',i.product_name,'variant_name',i.variant_name,'size',i.size,'quantity',i.quantity,'unit_price',i.unit_price,'total_price',i.total_price)) AS rows FROM public.pos_sale_items i WHERE i.sale_id=s.id) items ON true), filtered AS MATERIALIZED (SELECT * FROM enriched e WHERE (p_filter='all' OR e.expedition_status=p_filter) AND (p_search='' OR strpos(lower(coalesce(e.customer_name,'')),lower(p_search))>0 OR strpos(lower(coalesce(e.customer_phone,'')),lower(p_search))>0 OR strpos(lower(coalesce(e.tiny_order_number,'')),lower(p_search))>0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(e.items) i WHERE strpos(lower(coalesce(i->>'product_name','')),lower(p_search))>0 OR strpos(lower(coalesce(i->>'sku','')),lower(p_search))>0))), page AS (SELECT * FROM filtered ORDER BY created_at DESC LIMIT greatest(1,least(coalesce(p_limit,50),100)) OFFSET greatest(0,coalesce(p_offset,0))), fiscal AS (SELECT DISTINCT ON(f.pos_sale_id) f.pos_sale_id,f.status,f.danfe_url,f.numero,c.cnpj AS company_cnpj FROM public.fiscal_documents f JOIN page p ON p.id=f.pos_sale_id LEFT JOIN public.companies c ON c.id=f.company_id WHERE f.status IN ('authorized','autorizada','autorizado') ORDER BY f.pos_sale_id,f.created_at DESC)
SELECT jsonb_build_object('orders',coalesce((SELECT jsonb_agg(to_jsonb(p)-'payment_details' ORDER BY created_at DESC) FROM page p),'[]'::jsonb),'total',(SELECT count(*) FROM filtered),'counts',jsonb_build_object('all',(SELECT count(*) FROM scope),'pending',(SELECT count(*) FROM scope WHERE expedition_status='pending'),'separating',(SELECT count(*) FROM scope WHERE expedition_status='separating'),'packed',(SELECT count(*) FROM scope WHERE expedition_status='packed'),'shipped',(SELECT count(*) FROM scope WHERE expedition_status='shipped')),'fiscal',coalesce((SELECT jsonb_object_agg(pos_sale_id,to_jsonb(f)-'pos_sale_id') FROM fiscal f),'{}'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.pos_shipments_page(uuid,text,text,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pos_shipments_page(uuid,text,text,integer,integer) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.pdv_sales_doorbell() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE sid uuid; BEGIN
IF TG_OP='INSERT' THEN FOR sid IN SELECT DISTINCT store_id FROM new_rows LOOP PERFORM realtime.send('{}'::jsonb,'sales_changed','pdv-store:'||sid::text,true); END LOOP;
ELSIF TG_OP='DELETE' THEN FOR sid IN SELECT DISTINCT store_id FROM old_rows LOOP PERFORM realtime.send('{}'::jsonb,'sales_changed','pdv-store:'||sid::text,true); END LOOP;
ELSE FOR sid IN SELECT DISTINCT store_id FROM (SELECT n.store_id FROM new_rows n JOIN old_rows o USING(id) WHERE n IS DISTINCT FROM o UNION SELECT o.store_id FROM old_rows o JOIN new_rows n USING(id) WHERE n IS DISTINCT FROM o) x LOOP PERFORM realtime.send('{}'::jsonb,'sales_changed','pdv-store:'||sid::text,true); END LOOP; END IF; RETURN NULL; END; $$;
REVOKE ALL ON FUNCTION public.pdv_sales_doorbell() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER pdv_sales_insert AFTER INSERT ON public.pos_sales REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.pdv_sales_doorbell();
CREATE TRIGGER pdv_sales_update AFTER UPDATE ON public.pos_sales REFERENCING NEW TABLE AS new_rows OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.pdv_sales_doorbell();
CREATE TRIGGER pdv_sales_delete AFTER DELETE ON public.pos_sales REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.pdv_sales_doorbell();
CREATE OR REPLACE FUNCTION public.pdv_live_doorbell() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE sid uuid; eids uuid[]; BEGIN
IF TG_OP='INSERT' THEN SELECT array_agg(DISTINCT event_id) INTO eids FROM new_rows;
ELSIF TG_OP='DELETE' THEN SELECT array_agg(DISTINCT event_id) INTO eids FROM old_rows;
ELSE SELECT array_agg(DISTINCT event_id) INTO eids FROM (SELECT n.event_id FROM new_rows n JOIN old_rows o USING(id) WHERE n IS DISTINCT FROM o UNION SELECT o.event_id FROM old_rows o JOIN new_rows n USING(id) WHERE n IS DISTINCT FROM o) x; END IF;
IF eids IS NULL THEN RETURN NULL; END IF;
FOR sid IN SELECT DISTINCT s.id FROM public.pos_stores s JOIN public.events e ON e.id=ANY(eids) WHERE s.is_active AND (e.default_store_id=s.id OR EXISTS(SELECT 1 FROM public.pos_store_whatsapp_numbers w WHERE w.store_id=s.id AND w.whatsapp_number_id=e.whatsapp_number_id) OR NOT EXISTS(SELECT 1 FROM public.pos_store_whatsapp_numbers w WHERE w.store_id=s.id)) LOOP PERFORM realtime.send('{}'::jsonb,'live_changed','pdv-store:'||sid::text,true); END LOOP; RETURN NULL; END; $$;
REVOKE ALL ON FUNCTION public.pdv_live_doorbell() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER pdv_live_insert AFTER INSERT ON public.orders REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION public.pdv_live_doorbell();
CREATE TRIGGER pdv_live_update AFTER UPDATE ON public.orders REFERENCING NEW TABLE AS new_rows OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.pdv_live_doorbell();
CREATE TRIGGER pdv_live_delete AFTER DELETE ON public.orders REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION public.pdv_live_doorbell();
CREATE POLICY pdv_store_doorbell_read ON realtime.messages FOR SELECT TO authenticated USING (realtime.topic() LIKE 'pdv-store:%' AND public.is_team_member((SELECT auth.uid())) AND EXISTS(SELECT 1 FROM public.pos_stores s WHERE 'pdv-store:'||s.id::text=realtime.topic()));